{
  "caseId": "BLDI-902906-68",
  "roast": "So you did the thing every LinkedIn influencer thinks is brave. Congratulations, you traded a chrome-plated paycheck for a post nobody asked to read. We've seen this movie before, and it always ends with ramen.",
  "departments": [
    {
      "name": "Gen Z Behaviour Department",
      "observations": ["You Googled 'is quitting brave' for validation.", "You'll post it on LinkedIn with a sunset filter.", "You called it 'a journey' not 'unemployed'."],
      "insight": "Your identity is now a status update.",
      "punchline": "The algorithm won't give you a participation trophy."
    },
    {
      "name": "Neighbour Surveillance Department",
      "observations": ["Your mum already knows.", "They can smell unemployment through the walls.", "Your neighbor's dog heard you cry on day one."],
      "insight": "Gossip travels faster than your severance notice.",
      "punchline": "Everyone on your street already knows your bio is a lie."
    },
    {
      "name": "Overthinking Department",
      "observations": ["You wrote a 12-step exit plan on Notion.", "You saved exactly 8 months of expenses—confidently.", "You already imagined your comeback TED Talk."],
      "insight": "You've over-planned the freedom you haven't earned yet.",
      "punchline": "The plan is the prison you built before quitting the real one."
    },
    {
      "name": "Financial Crime Department",
      "observations": ["Your savings rate is 0.3 percent.", "You spent the sign-on bonus on a standing desk.", "Your 'financial runway' has a hole in it."],
      "insight": "Delusions become expensive the moment the bills arrive.",
      "punchline": "Google will not be your co-signer at the bank."
    },
    {
      "name": "Department of Future Regret",
      "observations": ["You will scroll this decision awake at 2am.", "The regret compound interest is already accruing.", "Every rejection email will echo precisely this day."],
      "insight": "Time grants neither wishes nor do-overs.",
      "punchline": "Future you is already filing the formal complaint."
    },
    {
      "name": "Reality Department",
      "observations": ["No one is coming to save you."],
      "insight": "You are wasting your limited hours on earth chasing a narrative of freedom that was never guaranteed.",
      "punchline": "You are entirely alone in this choice."
    }
  ],
  "verdict": "APPROVED WITH REGRET",
  "verdictReason": "The citizen possesses the legal and cognitive capacity to sign the resignation. However, every department unanimously warns that the decision reflects emotional impulsivity masquerading as liberation, and the ledger of future suffering has already been opened."
}

